import {enterReview} from './enter-review';
import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
import {expect,test} from '@playwright/test';
import {scan} from '../../tools/rtl-scanner/src/scan';
const findingId='RTL.BIDI.ISOLATION:741d2ce2aec3a86cf2db37ea',sourcePath='apps/invoicing/src/components/InvoiceTable.tsx',replacement='<bdi dir="auto">{i.id}</bdi>',hash=(s:string)=>createHash('sha256').update(s).digest('hex');
test('manual Apply & Preview isolates one shared-inventory patch and renders candidate LTR and RTL',async({page,context},info)=>{
 const root=info.config.metadata.portableFixtureRoot as string;if(!root?.includes('rtl-analyzer-e2e-'))throw Error('DISPOSABLE_FIXTURE_REQUIRED');const original=readFileSync(join(root,sourcePath),'utf8'),events:any[]=[],errors:string[]=[];
 page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(r.method()==='POST'&&r.url().includes('127.0.0.1:4318'))events.push({url:r.url(),body:r.postDataJSON()})});
 await page.goto('?finding='+encodeURIComponent(findingId),{waitUntil:'domcontentloaded'});const data=JSON.parse((await page.locator('#rtl-dashboard-data').textContent())!);const report=await page.request.get(new URL('rtl-report.json',page.url()).href).then(r=>r.json()),live=await scan(root);expect(live.inputDigest).toBe(data.inputDigest);expect(live.policyDigest).toBe(data.policyDigest);expect(data.schemaVersion).toBe(report.schemaVersion);
 const snippet=data.sourceSnippets.findings.find((s:any)=>s.findingId===findingId);expect(snippet.available).toBe(true);const window=data.sourceSnippets.sources.find((s:any)=>s.id===snippet.sourceId);expect(window.path).toBe(sourcePath);for(const line of window.lines)expect(line.text).toBe(original.split('\n')[line.number-1]);
 await enterReview(page);await expect(page.locator('.after-card pre')).toHaveText(replacement);
 const snapshot=()=>page.request.get('http://127.0.0.1:4318/review/workflows?'+new URLSearchParams({mode:'one-by-one',inputDigest:report.inputDigest,policyDigest:report.policyDigest})).then(r=>r.json()).then(r=>r.workflow);
 const before=await snapshot(),entry=before.entries.find((e:any)=>e.finding.id===findingId),patch=entry.patch;expect(before.session).toBeUndefined();expect(patch.expectedSha256).toBe(hash(original.slice(patch.startOffset,patch.endOffset)));expect(before.files.find((f:any)=>f.path===sourcePath).originalSha256).toBe(hash(original));await page.locator('.finding.selected').click();await expect(page.locator('.after-card pre')).toHaveText(replacement);expect(events.filter(e=>e.url.endsWith('/review/workflows'))).toHaveLength(1);
 await page.getByRole('button',{name:'Apply & Preview',exact:true}).click();await expect(page.locator('.component-after .embedded-state')).toHaveAttribute('data-state','ready',{timeout:30000});const w=await snapshot(),session=w.session;expect(session.runtime.status).toBe('healthy');expect(w.entries.filter((e:any)=>e.applied)).toHaveLength(1);expect(events.filter(e=>e.url.endsWith('/change'))).toHaveLength(1);expect(events.filter(e=>e.url.endsWith('/runtime'))).toHaveLength(1);
 const expected=original.slice(0,patch.startOffset)+replacement+original.slice(patch.endOffset);const file=w.files.find((f:any)=>f.path===sourcePath);expect(file.before).toBe(original);expect(file.after).toBe(expected);expect(file.candidateSha256).toBe(hash(expected));expect(entry.finding.range.start.line).toBe(original.slice(0,patch.startOffset).split('\n').length);
 const module=await page.request.get(session.runtime.origin+'/src/components/InvoiceTable.tsx').then(r=>r.text());const encoded=module.match(/sourceMappingURL=data:application\/json;base64,([^\s]+)/);expect(encoded).not.toBeNull();const map=JSON.parse(Buffer.from(encoded![1],'base64').toString());expect(map.file).toContain('/rtl-review-');expect(map.file).not.toBe(join(root,sourcePath));const candidate=readFileSync(map.file,'utf8');expect(candidate).toBe(expected);expect(map.sourcesContent[0]).toBe(candidate);expect(hash(readFileSync(join(root,sourcePath),'utf8'))).toBe(hash(original));await page.screenshot({path:info.outputPath('candidate-ready.png'),fullPage:true});
 for(const mode of ['LTR','RTL']){const opened=context.waitForEvent('page');await page.locator('.route-actions').getByRole('button',{name:mode+' Preview',exact:true}).click();const popup=await opened;popup.on('pageerror',e=>errors.push(e.message));await popup.waitForLoadState('domcontentloaded');expect(new URL(popup.url()).origin).toBe(session.runtime.origin);await expect(popup.locator('html')).toHaveAttribute('dir',mode.toLowerCase());await expect(popup.locator('.invoice-link bdi[dir="auto"]').first()).toHaveText(/INV-/);await popup.screenshot({path:info.outputPath('candidate-'+mode.toLowerCase()+'.png'),fullPage:true});await popup.close()}
 expect(errors).toEqual([]);expect(events.filter(e=>/\/(validate|apply|rollback|records|evidence)$/.test(new URL(e.url).pathname))).toHaveLength(0);writeFileSync(info.outputPath('acceptance.json'),JSON.stringify({root,workflow:w,reportIdentity:{inputDigest:report.inputDigest,policyDigest:report.policyDigest},candidateFile:map.file,originalBefore:hash(original),originalAfter:hash(readFileSync(join(root,sourcePath),'utf8')),candidateHash:hash(candidate),events,errors},null,2));
});
